
public class Floid {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
int number=1;
		for (int i = 1; i <= 15; i++)
		{ 
			for (int j = 1; j <= i; j++) 
			{ 
				System.out.print(number + " ");
				number++; 
				} 
			System.out.println();
			} 
		}

	//Read more: https://javarevisited.blogspot.com/2014/12/how-to-print-floyds-triangle-in-java.html#ixzz61TatkuSe

}
